function analyticsChart(id,type,labels,values,name){const node=document.querySelector(`#${id}`);if(!node||!window.echarts)return;const chart=echarts.init(node);chart.setOption({aria:{enabled:true},color:['#08786f','#39a99f','#082e64','#e3a63b','#a62c28'],tooltip:{trigger:type==='pie'?'item':'axis'},grid:type==='pie'?undefined:{left:45,right:20,top:30,bottom:55},xAxis:type==='pie'?undefined:{type:'category',data:labels,axisLabel:{rotate:labels.length>8?35:0}},yAxis:type==='pie'?undefined:{type:'value',minInterval:1},series:[{name,type,data:type==='pie'?labels.map((label,index)=>({name:analyticsLabel(label),value:values[index]})):values,smooth:type==='line'}]});new ResizeObserver(()=>chart.resize()).observe(node);}
