function enhanceRecordTable(tableElement){const rows=[...tableElement.tBodies[0].rows].filter(row=>row.cells.length>1),panel=tableElement.closest('.panel'),tableShell=tableElement.closest('.table-shell')||tableElement,tools=document.createElement('div'),search=document.createElement('input'),summary=document.createElement('span'),previous=document.createElement('button'),next=document.createElement('button');tools.className='list-tools';search.type='search';search.placeholder='Search records';search.setAttribute('aria-label','Search records');previous.type=next.type='button';previous.textContent='Previous';next.textContent='Next';tools.append(search,summary,previous,next);panel.insertBefore(tools,tableShell);let page=1;const pageSize=25,render=()=>{const matches=rows.filter(row=>row.textContent.toLowerCase().includes(search.value.trim().toLowerCase())),pages=Math.max(1,Math.ceil(matches.length/pageSize));page=Math.min(page,pages);const start=(page-1)*pageSize,end=Math.min(start+pageSize,matches.length),visible=new Set(matches.slice(start,end));rows.forEach(row=>row.hidden=!visible.has(row));summary.textContent=matches.length?`Showing ${start+1}-${end} of ${matches.length} · Page ${page} of ${pages}`:'No records found';previous.disabled=page===1;next.disabled=page===pages};search.addEventListener('input',()=>{page=1;render()});previous.onclick=()=>{page--;render()};next.onclick=()=>{page++;render()};render()}
