const sidebarToggle=document.querySelector('#sidebar-toggle'),storedCollapsed=localStorage.getItem('tess-portal-sidebar')==='collapsed';
layout.classList.toggle('nav-collapsed',storedCollapsed);
sidebarToggle.setAttribute('aria-expanded',String(!storedCollapsed));
sidebarToggle.onclick=()=>{if(matchMedia('(max-width:800px)').matches){document.body.classList.toggle('mobile-nav-open');return}const collapsed=layout.classList.toggle('nav-collapsed');sidebarToggle.setAttribute('aria-expanded',String(!collapsed));sidebarToggle.setAttribute('aria-label',collapsed?'Expand navigation':'Collapse navigation');localStorage.setItem('tess-portal-sidebar',collapsed?'collapsed':'expanded')};

function openCommandPalette(){
 const input=document.querySelector('#command-search'),results=document.querySelector('#command-results');
 const render=()=>{const term=input.value.trim().toLowerCase(),items=[...document.querySelectorAll('#sidebar [data-view]:not([hidden])')].filter(button=>!button.closest('[hidden]')&&button.textContent.toLowerCase().includes(term));results.innerHTML=items.length?items.map(button=>`<button type="button" data-command-view="${esc(button.dataset.view)}"><span>${esc(button.textContent.trim())}</span><small>Open page</small></button>`).join(''):'<p class="muted">No matching page.</p>';results.querySelectorAll('[data-command-view]').forEach(button=>button.onclick=()=>{commandDialog.close();document.querySelector(`#sidebar [data-view="${CSS.escape(button.dataset.commandView)}"]`)?.click()})};
 input.value='';render();commandDialog.showModal();input.focus();input.oninput=render;
}
document.querySelector('#command-open').onclick=openCommandPalette;
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openCommandPalette()}if(event.key==='Escape')document.body.classList.remove('mobile-nav-open')});

