const supportDirectoryView=support;
support=async()=>{await supportDirectoryView();const state=directoryState('support'),search=document.querySelector('#ticket-search'),status=document.querySelector('#ticket-status'),category=document.querySelector('#ticket-category');if(search)search.value=state.search;if(status)status.value=state.filters.status||'';if(category)category.value=state.filters.category||'';let timer;const reload=()=>{clearTimeout(timer);timer=setTimeout(()=>{state.search=search?.value.trim()||'';state.filters={status:status?.value||'',category:category?.value||''};state.cursor='';setPortalLoading('tickets');support().catch(showError)},250)};if(search)search.oninput=reload;if(status)status.oninput=reload;if(category)category.oninput=reload;enhanceServerDirectory('support',apiPagination.get('support'),support,{search:false,label:'tickets'})};
views.support=support;
