async function restorePortalRoute(){
 if(!location.hash||!me)return;
 const match=/^#([^?]+)(?:\?facility=([^&]+))?/.exec(location.hash);if(!match)return;
 const view=decodeURIComponent(match[1]),routeFacility=match[2]?decodeURIComponent(match[2]):null,stored=JSON.parse(sessionStorage.getItem('tess-selected-facility')||'null');
 if(routeFacility&&stored?.id===routeFacility){facilityId=stored.id;selectedFacilityName=stored.name;nav();}
 const button=[...document.querySelectorAll(`#sidebar [data-view="${CSS.escape(view)}"]`)].find(item=>!item.hidden&&!item.closest('[hidden]'));
 if(!button||!views[view])return;
 document.querySelectorAll('[data-view]').forEach(item=>item.removeAttribute('aria-current'));button.setAttribute('aria-current','page');setPortalLoading(button.textContent.trim());await views[view]();
}
let routeAttempts=0;const routeTimer=setInterval(()=>{if(me){clearInterval(routeTimer);restorePortalRoute().catch(showError)}else if(++routeAttempts>40)clearInterval(routeTimer)},100);
addEventListener('popstate',()=>restorePortalRoute().catch(showError));

if(!isAdminHost){
 const sessionDialog=document.querySelector('#session-dialog');let sessionTimer;
 const armSessionWarning=()=>{clearTimeout(sessionTimer);sessionTimer=setTimeout(()=>sessionDialog.showModal(),11*60*60*1000+45*60*1000)};
 armSessionWarning();
 document.querySelector('#session-continue').onclick=async()=>{try{await api('auth/refresh',{method:'POST',body:'{}'});sessionDialog.close();armSessionWarning()}catch(err){showError(err)}};
}
